#!/usr/bin/env node
/** The command: `wrap <width>` fills lines, `justify <width>` also pads them. */

import { readFileSync } from 'node:fs'
import { breakLines, justifyLine, paragraphs } from './layout.js'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Every input line, with the trailing newline's empty tail dropped. */
function lines() {
  const split = readFileSync(0, 'utf8').split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

const argv = process.argv.slice(2)
if (argv.length !== 2 || (argv[0] !== 'wrap' && argv[0] !== 'justify')) fail('usage: cli.js wrap|justify <width>')
if (!/^[1-9]\d*$/u.test(argv[1])) fail('width must be a positive integer')

const limit = Number(argv[1])
const out = []
for (const words of paragraphs(lines())) {
  if (out.length > 0) out.push('')
  const broken = breakLines(words, limit)
  broken.forEach((line, index) => {
    const last = index === broken.length - 1
    out.push(argv[0] === 'wrap' || last ? line.join(' ') : justifyLine(line, limit))
  })
}
process.stdout.write(out.map(line => `${line}\n`).join(''))

import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))
const FOX = 'the quick brown fox jumps over the lazy dog\n'

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

test('wrap fills each line greedily up to the width', () => {
  assert.deepEqual(run(['wrap', '12'], FOX), { code: 0, out: 'the quick\nbrown fox\njumps over\nthe lazy dog\n', err: '' })
})

test('wrap joins words with exactly one space', () => {
  assert.equal(run(['wrap', '40'], 'a   b\t\tc\n').out, 'a b c\n')
})

test('wrap keeps paragraphs apart with one blank line', () => {
  assert.equal(run(['wrap', '8'], 'one two\n\n\nthree\n').out, 'one two\n\nthree\n')
})

test('wrap ignores blank lines around the text', () => {
  assert.equal(run(['wrap', '8'], '\n\nonly\n\n').out, 'only\n')
})

test('wrap re-flows lines that the input had already broken', () => {
  assert.equal(run(['wrap', '11'], 'alpha\nbeta gamma\ndelta\n').out, 'alpha beta\ngamma delta\n')
})

test('justify pads the interior gaps to the exact width', () => {
  assert.equal(run(['justify', '12'], FOX).out, 'the    quick\nbrown    fox\njumps   other\n'.replace('other', 'over') + 'the lazy dog\n')
})

test('justify leaves the last line of a paragraph alone', () => {
  assert.equal(run(['justify', '10'], 'a b c\n').out, 'a b c\n')
})

test('justify leaves a one-word line alone', () => {
  assert.equal(run(['justify', '9'], 'alpha beta gamma\n').out, 'alpha\nbeta\ngamma\n')
})

test('a word longer than the width takes a line of its own', () => {
  assert.equal(run(['wrap', '5'], 'supercalifragilistic x\n').out, 'supercalifragilistic\nx\n')
})

test('a soft hyphen offers a break point and prints a hyphen', () => {
  assert.equal(run(['wrap', '8'], 'aaa hy­phen­ation bbb\n').out, 'aaa hy-\nphen-\nation\nbbb\n')
})

test('an unused soft hyphen disappears from the output', () => {
  assert.equal(run(['wrap', '40'], 'hy­phen\n').out, 'hyphen\n')
})

test('a combining mark takes no column', () => {
  assert.equal(run(['wrap', '4'], 'ábcd e\n').out, 'ábcd\ne\n')
})

test('a wide character takes two columns', () => {
  assert.equal(run(['wrap', '4'], '漢字 ab\n').out, '漢字\nab\n')
})

test('empty input prints nothing and succeeds', () => {
  assert.deepEqual(run(['wrap', '10'], ''), { code: 0, out: '', err: '' })
})

test('an unknown mode is rejected', () => {
  const result = run(['fill', '10'], '')
  assert.equal(result.code, 2)
  assert.equal(result.out, '')
  assert.equal(result.err, 'error: usage: cli.js wrap|justify <width>\n')
})

test('a width of zero is rejected', () => {
  assert.equal(run(['wrap', '0'], '').err, 'error: width must be a positive integer\n')
})

#!/usr/bin/env node
/**
 * Regenerate `cases.json` by running the reference on a fixed corpus: the
 * hand-written corners carry weight 3, the seeded paragraphs weight 1. The
 * corpus and the generator are deterministic, so a rerun rewrites the same
 * bytes.
 *
 *   node generate-cases.mjs
 */

import { spawnSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('./src/cli.js', import.meta.url))
const out = fileURLToPath(new URL('./cases.json', import.meta.url))

/** One 32-bit linear congruential stream, so a rerun draws the same corpus. */
function rng(seed) {
  let state = seed >>> 0
  return limit => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0
    return state % limit
  }
}

const SOFT = '­'
const FOX = 'the quick brown fox jumps over the lazy dog\n'
const HYPHENS = `aaa hy${SOFT}phen${SOFT}ation bbb ex${SOFT}tra${SOFT}or${SOFT}di${SOFT}nary\n`
const MIXED = `ábc 漢字漢字 xy zz̀́ ＡＢ tail\n`

const CORNERS = [
  [['wrap', '12'], FOX], [['justify', '12'], FOX], [['wrap', '1'], FOX], [['justify', '1'], FOX],
  [['wrap', '43'], FOX], [['justify', '43'], FOX], [['wrap', '44'], FOX], [['wrap', '7'], FOX], [['justify', '7'], FOX],
  [['wrap', '8'], HYPHENS], [['justify', '8'], HYPHENS], [['wrap', '5'], HYPHENS], [['wrap', '40'], HYPHENS],
  [['wrap', '6'], MIXED], [['justify', '6'], MIXED], [['wrap', '3'], MIXED], [['wrap', '30'], MIXED],
  [['wrap', '10'], ''], [['justify', '10'], ''],
  [['wrap', '10'], '\n\n\n'], [['wrap', '10'], '   \n\t\n'],
  [['wrap', '10'], 'one two\n\n\nthree four\n'], [['justify', '10'], 'one two\n\n\nthree four\n'],
  [['wrap', '10'], '\n\nonly\n\n'],
  [['wrap', '11'], 'alpha\nbeta gamma\ndelta\n'],
  [['wrap', '5'], 'supercalifragilistic x\n'], [['justify', '5'], 'supercalifragilistic x\n'],
  [['wrap', '4'], `su${SOFT}per x\n`], [['wrap', '3'], `su${SOFT}per x\n`], [['wrap', '2'], `su${SOFT}per x\n`],
  [['wrap', '9'], `${SOFT}abc def\n`], [['wrap', '9'], `abc${SOFT} def\n`],
  [['justify', '20'], 'a bb ccc dddd e f g\n'], [['justify', '19'], 'a bb ccc dddd e f g\n'],
  [['justify', '18'], 'a bb ccc dddd e f g\n'], [['justify', '13'], 'a bb ccc dddd e f g\n'],
  [['wrap', '10'], 'a   b\t\tc\n'],
  [['wrap', '10'], 'trailing   \n'],
  [['justify', '12'], 'one two\nthree four five six\n'],
  [['wrap', '2'], '漢 a\n'], [['justify', '2'], '漢 a\n'],
  [['wrap', '0'], FOX], [['wrap', '-3'], FOX], [['wrap', '03'], FOX], [['wrap', 'ten'], FOX],
  [['fill', '10'], FOX], [['wrap'], FOX], [['wrap', '10', '20'], FOX], [[], FOX],
]

const WORDS = [
  'alpha', 'be', 'c', 'delta', 'ee', 'fig', 'grape', 'hi', 'ionosphere', 'jam',
  `mul${SOFT}ti`, `over${SOFT}flow${SOFT}ing`, '漢字', 'áé', 'ＡＢＣ', 'zzzzzzzzzzzz',
]
const WIDTHS = ['3', '5', '8', '12', '20', '31']

const draw = rng(20260907)
const cases = []
const push = (weight, argv, stdin) => {
  cases.push({ id: `${weight === 3 ? 'corner' : 'seeded'}-${String(cases.length + 1).padStart(3, '0')}`, weight, argv, stdin })
}
for (const [argv, stdin] of CORNERS) push(3, argv, stdin)

const seeded = new Set()
while (cases.length < 160) {
  const blocks = 1 + draw(2)
  const body = []
  for (let block = 0; block < blocks; block += 1) {
    if (block > 0) body.push('')
    const count = 2 + draw(9)
    body.push(Array.from({ length: count }, () => WORDS[draw(WORDS.length)]).join(' '))
  }
  const stdin = `${body.join('\n')}\n`
  const argv = [draw(2) === 0 ? 'wrap' : 'justify', WIDTHS[draw(WIDTHS.length)]]
  const key = `${argv.join(' ')} ${stdin}`
  if (seeded.has(key)) continue
  seeded.add(key)
  push(1, argv, stdin)
}

const bodies = cases.map(one => {
  const run = spawnSync(process.execPath, [cli, ...one.argv], { encoding: 'utf8', input: one.stdin })
  if (run.error !== undefined) throw run.error
  return {
    id: one.id,
    weight: one.weight,
    argv: one.argv,
    stdin: one.stdin,
    exitCode: run.status,
    stdout: run.stdout,
    stderr: run.stderr,
    channels: ['exit', 'stdout', 'stderr'],
  }
})
writeFileSync(out, `${JSON.stringify(bodies, undefined, 1)}\n`)
process.stdout.write(`wrote ${bodies.length} cases\n`)

