/** Longest common subsequence over lines, and the changed regions it implies. */

/**
 * The matched index pairs of a longest common subsequence, taking the earliest
 * match whenever two subsequences are equally long.
 * @param left - the first line array.
 * @param right - the second line array.
 * @returns pairs `[leftIndex, rightIndex]`, ascending in both coordinates.
 */
export function commonPairs(left, right) {
  const table = Array.from({ length: left.length + 1 }, () => new Array(right.length + 1).fill(0))
  for (let index = left.length - 1; index >= 0; index -= 1) {
    for (let other = right.length - 1; other >= 0; other -= 1) {
      table[index][other] = left[index] === right[other]
        ? table[index + 1][other + 1] + 1
        : Math.max(table[index + 1][other], table[index][other + 1])
    }
  }
  const pairs = []
  let index = 0
  let other = 0
  while (index < left.length && other < right.length) {
    if (left[index] === right[other]) {
      pairs.push([index, other])
      index += 1
      other += 1
    } else if (table[index + 1][other] >= table[index][other + 1]) index += 1
    else other += 1
  }
  return pairs
}

/**
 * The regions in which `other` departs from `base`, as replacements of a run of
 * `base` by a run of `other`; a pure insertion has a base length of 0 and a pure
 * deletion an other length of 0.
 * @param base - the common ancestor's lines.
 * @param other - the derived lines.
 * @returns the changed regions, in base order.
 */
export function changes(base, other) {
  const out = []
  let baseAt = 0
  let otherAt = 0
  for (const [basePair, otherPair] of [...commonPairs(base, other), [base.length, other.length]]) {
    if (basePair > baseAt || otherPair > otherAt) {
      out.push({ baseStart: baseAt, baseLength: basePair - baseAt, otherStart: otherAt, otherLength: otherPair - otherAt })
    }
    baseAt = basePair + 1
    otherAt = otherPair + 1
  }
  return out
}

/** The three-way region walk and the verdict each region earns. */

import { changes } from './diff.js'

/** Whether two line arrays hold the same lines in the same order. */
function same(left, right) {
  return left.length === right.length && left.every((line, index) => line === right[index])
}

/**
 * Split the three documents into regions: runs the two sides left alone, runs
 * only one side touched, and runs both touched.
 * @param mine - the first side's lines.
 * @param base - the common ancestor's lines.
 * @param theirs - the second side's lines.
 * @returns the regions in base order, each carrying the lines it resolves to and its kind.
 */
export function regions(mine, base, theirs) {
  const hunks = [
    ...changes(base, mine).map(hunk => ({ ...hunk, side: 'mine' })),
    ...changes(base, theirs).map(hunk => ({ ...hunk, side: 'theirs' })),
  ].sort((left, right) => left.baseStart - right.baseStart)
  const out = []
  let at = 0
  const stableTo = end => {
    if (end > at) out.push({ kind: 'stable', lines: base.slice(at, end) })
    at = end
  }
  while (hunks.length > 0) {
    const first = hunks.shift()
    const start = first.baseStart
    let end = first.baseStart + first.baseLength
    const group = [first]
    stableTo(start)
    while (hunks.length > 0 && hunks[0].baseStart <= end) {
      end = Math.max(end, hunks[0].baseStart + hunks[0].baseLength)
      group.push(hunks.shift())
    }
    if (group.length === 1) {
      const lines = (first.side === 'mine' ? mine : theirs).slice(first.otherStart, first.otherStart + first.otherLength)
      out.push({ kind: first.side, lines })
      at = end
      continue
    }
    // Both sides reach into this region, so each side's extent is its own
    // hunks' span widened by however much the region overruns them in the base.
    const extent = side => {
      const own = group.filter(hunk => hunk.side === side)
      if (own.length === 0) return { from: 0, to: 0 }
      const from = Math.min(...own.map(hunk => hunk.otherStart))
      const to = Math.max(...own.map(hunk => hunk.otherStart + hunk.otherLength))
      const baseFrom = Math.min(...own.map(hunk => hunk.baseStart))
      const baseTo = Math.max(...own.map(hunk => hunk.baseStart + hunk.baseLength))
      return { from: from + (start - baseFrom), to: to + (end - baseTo) }
    }
    const mineSpan = extent('mine')
    const theirsSpan = extent('theirs')
    const mineLines = mine.slice(mineSpan.from, mineSpan.to)
    const theirsLines = theirs.slice(theirsSpan.from, theirsSpan.to)
    const baseLines = base.slice(start, end)
    if (same(mineLines, theirsLines)) out.push({ kind: 'both', lines: mineLines })
    else if (same(mineLines, baseLines)) out.push({ kind: 'theirs', lines: theirsLines })
    else if (same(theirsLines, baseLines)) out.push({ kind: 'mine', lines: mineLines })
    else out.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    at = end
  }
  stableTo(base.length)
  return out
}

/**
 * Render the regions as merged text.
 * @param parts - the regions from {@link regions}.
 * @param withBase - whether a conflict shows the base section between its sides.
 * @returns the merged lines.
 */
export function render(parts, withBase) {
  const out = []
  for (const region of parts) {
    if (region.kind !== 'conflict') {
      out.push(...region.lines)
      continue
    }
    out.push('<<<<<<< mine', ...region.mine)
    if (withBase) out.push('||||||| base', ...region.base)
    out.push('=======', ...region.theirs, '>>>>>>> theirs')
  }
  return out
}

/**
 * Render the regions as one classification line each.
 * @param parts - the regions from {@link regions}.
 * @returns the report lines.
 */
export function describe(parts) {
  return parts.map(region => (region.kind === 'conflict'
    ? `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`
    : `${region.kind} ${region.lines.length}`))
}

#!/usr/bin/env node
/** The command: merge three documents, with or without the base section, or report the regions. */

import { readFileSync } from 'node:fs'
import { describe, regions, render } from './merge.js'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Every input line, with the trailing newline's empty tail dropped. */
function lines() {
  const split = readFileSync(0, 'utf8').split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (argv.length !== 1 || (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions')) fail('usage: cli.js merge|merge2|regions')

const parts = [[]]
for (const line of lines()) {
  if (line === '%%%') parts.push([])
  else parts[parts.length - 1].push(line)
}
if (parts.length !== 3) fail('expected three parts separated by %%%')

const found = regions(parts[0], parts[1], parts[2])
const out = mode === 'regions' ? describe(found) : render(found, mode === 'merge')
process.stdout.write(out.map(line => `${line}\n`).join(''))
process.exit(found.some(region => region.kind === 'conflict') ? 1 : 0)

import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))

function run(argv, mine, base, theirs) {
  const input = [mine, base, theirs].map(part => part.map(line => `${line}\n`).join('')).join('%%%\n')
  const result = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

test('three identical documents merge to themselves', () => {
  assert.deepEqual(run(['merge'], ['a', 'b'], ['a', 'b'], ['a', 'b']), { code: 0, out: 'a\nb\n', err: '' })
})

test('a change only one side made is taken', () => {
  assert.deepEqual(run(['merge'], ['a', 'X'], ['a', 'b'], ['a', 'b']), { code: 0, out: 'a\nX\n', err: '' })
})

test('a change only the other side made is taken', () => {
  assert.equal(run(['merge'], ['a', 'b'], ['a', 'b'], ['a', 'Z']).out, 'a\nZ\n')
})

test('changes in different places both survive', () => {
  assert.equal(run(['merge'], ['X', 'b', 'c'], ['a', 'b', 'c'], ['a', 'b', 'Z']).out, 'X\nb\nZ\n')
})

test('the same change on both sides is not a conflict', () => {
  assert.deepEqual(run(['merge'], ['a', 'X'], ['a', 'b'], ['a', 'X']), { code: 0, out: 'a\nX\n', err: '' })
})

test('a line only one side inserted is kept', () => {
  assert.equal(run(['merge'], ['a', 'Q', 'b'], ['a', 'b'], ['a', 'b']).out, 'a\nQ\nb\n')
})

test('a line only one side deleted stays deleted', () => {
  assert.equal(run(['merge'], ['a', 'c'], ['a', 'b', 'c'], ['a', 'b', 'c']).out, 'a\nc\n')
})

test('two different changes to one line conflict and exit 1', () => {
  const result = run(['merge'], ['a', 'X', 'c'], ['a', 'b', 'c'], ['a', 'Y', 'c'])
  assert.equal(result.code, 1)
  assert.equal(result.out, 'a\n<<<<<<< mine\nX\n||||||| base\nb\n=======\nY\n>>>>>>> theirs\nc\n')
  assert.equal(result.err, '')
})

test('merge2 leaves the base section out of a conflict', () => {
  assert.equal(
