/** Parsing the ballot file and running the instant-runoff rounds over it. */

/** Raised for input the specification rejects; `line` is 0 when the failure names none. */
export class BallotError extends Error {
  /**
   * @param message - the reported reason.
   * @param line - the 1-based input line, or 0 when the failure names none.
   */
  constructor(message, line) {
    super(message)
    this.name = 'BallotError'
    this.line = line
  }
}

/** A candidate name: letters, digits, underscore and dash. */
const NAME = /^[A-Za-z0-9_-]+$/u

/** A ballot multiplier: an unsigned decimal integer of at least 1, with no leading zero. */
const COUNT = /^[1-9]\d*$/u

/**
 * Parse the directive lines into the candidate list and the ballots.
 * @param lines - the input lines, in order.
 * @returns the declared candidates in declaration order and the ballots as `{ count, ranking }`.
 * @throws {BallotError} for any malformed directive.
 */
export function parse(lines) {
  let candidates
  const ballots = []
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].trim()
    const at = index + 1
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/u)
    if (words[0] === 'candidates') {
      if (candidates !== undefined || ballots.length > 0) throw new BallotError('candidates must be declared once, before any ballot', at)
      if (words.length < 2) throw new BallotError('expected candidates <name>...', at)
      const seen = new Set()
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) throw new BallotError(`invalid candidate name ${name}`, at)
        if (seen.has(name)) throw new BallotError(`candidate ${name} is declared twice`, at)
        seen.add(name)
      }
      candidates = words.slice(1)
      continue
    }
    if (words[0] === 'ballot') {
      if (candidates === undefined) throw new BallotError('candidates must be declared once, before any ballot', at)
      if (words.length < 3) throw new BallotError('expected ballot <count> <candidate>...', at)
      if (!COUNT.test(words[1])) throw new BallotError('count must be a positive integer', at)
      const ranking = words.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!candidates.includes(name)) throw new BallotError(`unknown candidate ${name}`, at)
        if (seen.has(name)) throw new BallotError(`candidate ${name} is repeated`, at)
        seen.add(name)
      }
      ballots.push({ count: Number(words[1]), ranking })
      continue
    }
    throw new BallotError(`unknown directive ${words[0]}`, at)
  }
  if (candidates === undefined) throw new BallotError('no candidates', 0)
  return { candidates, ballots }
}

/** The counts one round gives each continuing candidate, plus the exhausted total. */
function count(ballots, continuing) {
  const tally = new Map([...continuing].map(name => [name, 0]))
  let exhausted = 0
  for (const ballot of ballots) {
    const choice = ballot.ranking.find(name => continuing.has(name))
    if (choice === undefined) exhausted += ballot.count
    else tally.set(choice, tally.get(choice) + ballot.count)
  }
  return { tally, exhausted }
}

/**
 * The candidate eliminated from a set that ties for the fewest votes: the one
 * that trailed in the earliest round where the tied candidates differed, and
 * the alphabetically last of them when no round ever separated them.
 * @param tied - the tied candidate names.
 * @param history - every round's tally so far, oldest first.
 * @returns the name to eliminate.
 */
function breakTie(tied, history) {
  for (const round of history) {
    const counts = tied.map(name => round.get(name))
    const fewest = Math.min(...counts)
    const trailing = tied.filter(name => round.get(name) === fewest)
    if (trailing.length < tied.length) return breakTie(trailing, history)
  }
  return [...tied].sort().pop()
}

/**
 * Run the rounds to a winner or to an exhausted electorate.
 * @param candidates - the declared candidates, in declaration order.
 * @param ballots - the parsed ballots.
 * @returns each round's tally, exhausted count and elimination, and the winner if there is one.
 */
export function run(candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []
  const history = []
  for (;;) {
    const { tally, exhausted } = count(ballots, continuing)
    history.push(tally)
    const active = [...tally.values()].reduce((sum, votes) => sum + votes, 0)
    if (active === 0) {
      rounds.push({ tally, exhausted })
      return { rounds }
    }
    const leader = [...tally.entries()].find(([, votes]) => votes * 2 > active)
    if (leader !== undefined) {
      rounds.push({ tally, exhausted })
      return { rounds, winner: leader[0] }
    }
    const fewest = Math.min(...tally.values())
    const tied = [...tally.keys()].filter(name => tally.get(name) === fewest)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)
    rounds.push({ tally, exhausted, eliminated })
    continuing.delete(eliminated)
  }
}

#!/usr/bin/env node
/** The command: `rounds` prints every round of the runoff, `tally` prints only the outcome. */

import { readFileSync } from 'node:fs'
import { BallotError, parse, run } from './election.js'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Every input line, with the trailing newline's empty tail dropped. */
function lines() {
  const split = readFileSync(0, 'utf8').split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'rounds' && argv[0] !== 'tally')) fail('usage: cli.js rounds|tally')

let election
try {
  election = parse(lines())
} catch (error) {
  if (!(error instanceof BallotError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

const result = run(election.candidates, election.ballots)
const out = []
if (argv[0] === 'rounds') {
  result.rounds.forEach((round, index) => {
    const ordered = [...round.tally.entries()].sort((left, right) => right[1] - left[1] || (left[0] < right[0] ? -1 : 1))
    out.push(`round ${index + 1}: ${ordered.map(([name, votes]) => `${name}=${votes}`).join(' ')} exhausted=${round.exhausted}`)
    if (round.eliminated !== undefined) out.push(`eliminated ${round.eliminated}`)
  })
} else {
  out.push(`rounds ${result.rounds.length}`)
}
out.push(result.winner === undefined ? 'no winner' : `winner ${result.winner}`)
process.stdout.write(out.map(line => `${line}\n`).join(''))

import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))
const RACE = 'candidates alice bob carol\nballot 4 alice bob\nballot 3 bob carol\nballot 2 carol bob\nballot 1 carol\n'

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

test('a first-round majority wins at once', () => {
  const input = 'candidates a b\nballot 3 a\nballot 1 b\n'
  assert.deepEqual(run(['rounds'], input), { code: 0, out: 'round 1: a=3 b=1 exhausted=0\nwinner a\n', err: '' })
})

test('the runoff transfers votes from the eliminated candidate', () => {
  assert.equal(run(['rounds'], RACE).out, 'round 1: alice=4 bob=3 carol=3 exhausted=0\neliminated carol\nround 2: bob=5 alice=4 exhausted=1\nwinner bob\n')
})

test('tally prints only the round count and the outcome', () => {
  assert.deepEqual(run(['tally'], RACE), { code: 0, out: 'rounds 2\nwinner bob\n', err: '' })
})

test('a ballot whose choices are all eliminated becomes exhausted', () => {
  assert.equal(run(['rounds'], 'candidates a b c\nballot 3 a\nballot 2 b\nballot 1 c\n').out, 'round 1: a=3 b=2 c=1 exhausted=0\neliminated c\nround 2: a=3 b=2 exhausted=1\nwinner a\n')
})

test('counts are listed by descending votes and then by name', () => {
  assert.equal(run(['rounds'], 'candidates zeta alpha\nballot 1 zeta\nballot 1 alpha\n').out.split('\n')[0], 'round 1: alpha=1 zeta=1 exhausted=0')
})

test('a candidate nobody ranked still appears with zero', () => {
  assert.equal(run(['rounds'], 'candidates a b c\nballot 1 a\n').out, 'round 1: a=1 b=0 c=0 exhausted=0\nwinner a\n')
})

test('an election with no ballot has no winner', () => {
  assert.deepEqual(run(['rounds'], 'candidates a b\n'), { code: 0, out: 'round 1: a=0 b=0 exhausted=0\nno winner\n', err: '' })
})

test('blank lines and comments are ignored', () => {
  assert.equal(run(['tally'], '# vote\n\ncandidates a\nballot 1 a\n').out, 'rounds 1\nwinner a\n')
})

test('a ballot before the candidates is rejected', () => {
  const result = run(['tally'], 'ballot 1 a\ncandidates a\n')
  assert.equal(result.code, 2)
  assert.equal(result.out, '')
  assert.equal(result.err, 'error: line 1: candidates must be declared once, before any ballot\n')
})

test('a second candidates line is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\ncandidates b\n').err, 'error: line 2: candidates must be declared once, before any ballot\n')
})

test('a ballot naming an undeclared candidate is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\nballot 1 z\n').err, 'error: line 2: unknown candidate z\n')
})

test('a ballot that repeats a candidate is rejected', () => {
  assert.equal(run(['tally'], 'candidates a b\nballot 1 a b a\n').err, 'error: line 2: candidate a is repeated\n')
})

test('a non-positive ballot count is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\nballot 0 a\n').err, 'error: line 2: count must be a positive integer\n')
})

test('an input with no candidates line is rejected', () => {
  assert.equal(run(['tally'], '# nothing\n').err, 'error: no candidates\n')
})

test('an unknown directive is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\nvote 1 a\n').err, 'error: line 2: unknown directive vote\n')
})

test('an unknown mode is rejected', () => {
  const result = run(['count'], RACE)
  assert.equal(result.code, 2)
  assert.equal(result.err, 'error: usage: cli.js rounds|tally\n')
})

