  let passed = 0
  for (const entry of entries) {
    const channels = entry.channels ?? ['exit', 'stdout']
    const run = spawnSync('node', [...command, ...entry.argv], { cwd, encoding: 'utf8', input: entry.stdin ?? '', timeout: 20_000 })
    const bad = (channels.includes('exit') && run.status !== entry.exitCode)
      || (channels.includes('stdout') && digest(run.stdout ?? '') !== digest(entry.stdout))
      || (channels.includes('stderr') && digest(run.stderr ?? '') !== digest(entry.stderr ?? ''))
    if (!bad) passed += 1
  }
  return passed
}

for (const name of names) {
  const dir = join(root, name)
  const task = JSON.parse(readFileSync(join(dir, 'task.json'), 'utf8'))
  const work = join(outDir, name)
  rmSync(work, { recursive: true, force: true })
  cpSync(dir, work, { recursive: true })
  rmSync(join(work, 'reference'), { recursive: true, force: true })
  const prompt = `${task.prompt} ${SHARED_RULES} ${HIDDEN_CASE_RULE}`
  const started = Date.now()
  const attempt = spawnSync('claude', [
    '-p', prompt,
    '--permission-mode', 'acceptEdits',
    '--allowedTools', 'Bash(node:*)', 'Read', 'Edit', 'Write',
    '--no-session-persistence',
  ], { cwd: work, encoding: 'utf8', timeout: TIMEOUT_MS, maxBuffer: 64 * 1024 * 1024 })
  const seconds = Math.round((Date.now() - started) / 1000)
  writeFileSync(join(outDir, `${name}.log`), `${attempt.stdout ?? ''}\n---stderr---\n${attempt.stderr ?? ''}\n`)
  const suite = spawnSync('node', ['--test', 'test/*.test.js'], { cwd: work, encoding: 'utf8', shell: true, timeout: 180_000 })
  const cased = task.checks.find(check => typeof check.cases === 'string')
  const entries = JSON.parse(readFileSync(join(dir, ...cased.cases.split('/')), 'utf8'))
  const command = cased.run.split(/\s+/u).slice(1)
  const passed = scoreCases(work, command, entries)
  const row = { task: name, visible: suite.status === 0 ? 'pass' : 'fail', hidden: `${passed}/${entries.length}`, seconds, cliStatus: attempt.status ?? 'timeout' }
  writeFileSync(join(outDir, `${name}.json`), `${JSON.stringify(row)}\n`)
  console.log(JSON.stringify(row))
}

/** The two limiter kinds, each keeping one state per key. */

/**
 * A token bucket. Tokens are held scaled by `per`, so a refill of `refill`
 * tokens every `per` ticks is exact integer arithmetic and no drift can build
 * up over a long replay.
 */
export class Bucket {
  /**
   * @param name - the policy's name, as a deny reports it.
   * @param capacity - tokens the bucket holds when full, at least 1.
   * @param refill - tokens added every `per` ticks.
   * @param per - the refill period in ticks, at least 1.
   */
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.state = new Map()
  }

  /** Bring one key's bucket up to `tick`, creating it full when it is new. */
  advance(key, tick) {
    const known = this.state.get(key)
    if (known === undefined) {
      const fresh = { tokens: this.capacity * this.per, at: tick }
      this.state.set(key, fresh)
      return fresh
    }
    known.tokens = Math.min(this.capacity * this.per, known.tokens + this.refill * (tick - known.at))
    known.at = tick
    return known
  }

  /** Whether the key has a whole token at this tick. */
  allows(key, tick) {
    return this.advance(key, tick).tokens >= this.per
  }

  /** Spend one token, which the caller has confirmed is there. */
  take(key, tick) {
    this.advance(key, tick).tokens -= this.per
  }
}

/** A sliding window over the ticks of the requests it accepted. */
export class Window {
  /**
   * @param name - the policy's name, as a deny reports it.
   * @param limit - accepted requests allowed in any window, at least 0.
   * @param span - the window's width in ticks, at least 1.
   */
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.state = new Map()
  }

  /** Drop the accepted ticks that have fallen out of the window ending at `tick`. */
  advance(key, tick) {
    const known = this.state.get(key) ?? []
    const kept = known.filter(when => when > tick - this.span)
    this.state.set(key, kept)
    return kept
  }

  /** Whether the window ending at this tick still has room. */
  allows(key, tick) {
    return this.advance(key, tick).length < this.limit
  }

  /** Record one accepted request at this tick. */
  take(key, tick) {
    this.advance(key, tick).push(tick)
  }
}

/** Parsing the limiter file and replaying its event log through the routed policies. */

import { Bucket, Window } from './policy.js'

/** Raised for input the specification rejects; `line` is the 1-based input line. */
export class LimitError extends Error {
  /**
   * @param message - the reported reason.
   * @param line - the 1-based input line.
   */
  constructor(message, line) {
    super(message)
    this.name = 'LimitError'
    this.line = line
  }
}

/** A policy name, a route prefix, or an event key: letters, digits, and `_ - . / :`. */
const WORD = /^[A-Za-z0-9_./:-]+$/u

/** An unsigned decimal integer, written without a sign and without a leading zero unless it is `0`. */
const NUMBER = /^(?:0|[1-9]\d*)$/u

/** Read one field as an integer of at least `least`. */
function integer(text, field, least, line) {
  if (!NUMBER.test(text) || Number(text) < least) {
    throw new LimitError(`${field} must be an integer of at least ${least}`, line)
  }
  return Number(text)
}

/**
 * Parse the directive lines into the declared policies, the routes, and the log.
 * @param lines - the input lines, in order.
 * @returns the policies by name, the routes as `{ prefix, policies }`, and the events.
 * @throws {LimitError} for any malformed or out-of-order directive.
 */
export function parse(lines) {
  const policies = new Map()
  const routes = []
  const events = []
  let last = 0
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].trim()
    const at = index + 1
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/u)
    const declaring = words[0] === 'bucket' || words[0] === 'window' || words[0] === 'route'
    if (declaring && events.length > 0) throw new LimitError('declarations must come before the first event', at)
    if (words[0] === 'bucket' || words[0] === 'window') {
      const arity = words[0] === 'bucket' ? 5 : 4
      if (words.length !== arity) {
        throw new LimitError(words[0] === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>', at)
      }
      if (!WORD.test(words[1])) throw new LimitError(`invalid policy name ${words[1]}`, at)
      if (policies.has(words[1])) throw new LimitError(`policy ${words[1]} is declared twice`, at)
      policies.set(words[1], words[0] === 'bucket'
        ? new Bucket(words[1], integer(words[2], 'capacity', 1, at), integer(words[3], 'refill', 0, at), integer(words[4], 'per', 1, at))
        : new Window(words[1], integer(words[2], 'limit', 0, at), integer(words[3], 'span', 1, at)))
      continue
    }
    if (words[0] === 'route') {
      if (words.length < 3) throw new LimitError('expected route <prefix> <policy>...', at)
      if (!WORD.test(words[1])) throw new LimitError(`invalid route prefix ${words[1]}`, at)
      if (routes.some(route => route.prefix === words[1])) throw new LimitError(`prefix ${words[1]} is routed twice`, at)
      for (const named of words.slice(2)) {
        if (!policies.has(named)) throw new LimitError(`unknown policy ${named}`, at)
      }
      routes.push({ prefix: words[1], policies: words.slice(2).map(named => policies.get(named)) })
      continue
    }
    if (words[0] === 'event') {
      if (words.length !== 3) throw new LimitError('expected event <tick> <key>', at)
      const tick = integer(words[1], 'tick', 0, at)
      if (tick < last) throw new LimitError(`tick ${tick} is before tick ${last}`, at)
      if (!WORD.test(words[2])) throw new LimitError(`invalid key ${words[2]}`, at)
      last = tick
      events.push({ tick, key: words[2] })
      continue
    }
    throw new LimitError(`unknown directive ${words[0]}`, at)
  }
  return { routes, events }
}

/**
 * Replay the log: every routed policy advances to the event's tick, all of them
 * must allow it, and only then does each of them record it.
 * @param routes - the declared routes, in declaration order.
 * @param events - the log, in tick order.
 * @returns one verdict per event, carrying the denying policy's name when it was denied.
 */
export function replay(routes, events) {
  return events.map(event => {
    const matching = routes
      .filter(route => event.key.startsWith(route.prefix))
      .sort((left, right) => right.prefix.length - left.prefix.length)[0]
    if (matching === undefined) return { ...event, allowed: true }
    const refused = matching.policies.find(policy => !policy.allows(event.key, event.tick))
    if (refused !== undefined) return { ...event, allowed: false, by: refused.name }
    for (const policy of matching.policies) policy.take(event.key, event.tick)
    return { ...event, allowed: true }
  })
}

