#!/usr/bin/env node
/** The command: `replay` verdicts every event, `summary` totals them per key. */

import { readFileSync } from 'node:fs'
import { LimitError, parse, replay } from './replay.js'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Every input line, with the trailing newline's empty tail dropped. */
function lines() {
  const split = readFileSync(0, 'utf8').split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'replay' && argv[0] !== 'summary')) fail('usage: cli.js replay|summary')

let parsed
try {
  parsed = parse(lines())
} catch (error) {
  if (!(error instanceof LimitError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

const verdicts = replay(parsed.routes, parsed.events)
const out = []
if (argv[0] === 'replay') {
  for (const verdict of verdicts) {
    out.push(`${verdict.tick} ${verdict.key} ${verdict.allowed ? 'allow' : `deny ${verdict.by}`}`)
  }
} else {
  const keys = [...new Set(verdicts.map(verdict => verdict.key))].sort()
  for (const key of keys) {
    const own = verdicts.filter(verdict => verdict.key === key)
    out.push(`${key} allowed=${own.filter(verdict => verdict.allowed).length} denied=${own.filter(verdict => !verdict.allowed).length}`)
  }
  out.push(`total allowed=${verdicts.filter(verdict => verdict.allowed).length} denied=${verdicts.filter(verdict => !verdict.allowed).length}`)
}
process.stdout.write(out.map(line => `${line}\n`).join(''))

{
  "id": "code:rate-limit-sim",
  "tier": 5,
  "domain": "systems",
  "title": "Replay an event log through token buckets and sliding windows",
  "prompt": "`src/cli.js` is the program; how the work is split across other files under `src/` is up to you. It takes exactly one argument, `replay` or `summary`, and reads a limiter file from standard input. Split the input on newlines and drop the empty tail a trailing newline leaves. Trim each line; ignore it when it is empty or begins with `#`; otherwise split it on runs of whitespace. Exit 0 whenever the file parses.\n\nA name, a route prefix and an event key are each one or more of the characters `A` to `Z`, `a` to `z`, `0` to `9`, `_`, `.`, `/`, `:` and `-`. Every count is an unsigned decimal integer written without a sign and without a leading zero unless it is exactly `0`.\n\n`bucket <name> <capacity> <refill> <per>` declares a token bucket, with a capacity of at least 1, a refill of at least 0, and a period of at least 1. `window <name> <limit> <span>` declares a sliding window, with a limit of at least 0 and a span of at least 1. Two policies may not share a name. `route <prefix> <policy>...` sends every key that starts with that prefix to those policies, in the order written; every policy must already be declared, and two routes may not share a prefix. `event <tick> <key>` is one arrival at that tick, and ticks never go backwards across the file. Once the first event appears no further `bucket`, `window` or `route` line may follow.\n\nEach policy keeps one independent state per key. A key is limited by the route whose prefix it starts with and which is longest among those that match; a key no route matches is always allowed. When an event arrives, every policy on its route first advances to the event's tick, then every one of them is asked, and only when all of them allow it does each of them record it. A denied event changes no policy's stored allowance.\n\nA token bucket holds `capacity` tokens and starts full when a key first reaches it. Advancing it to a tick adds `refill` tokens for every `per` ticks that passed since it last advanced for that key, without ever passing the capacity, and partial periods accumulate exactly: after `n` ticks the bucket holds `refill` times `n` divided by `per` more tokens than it did, and that fraction is never rounded away. It allows a request when it holds at least one whole token, and recording one spends exactly one.\n\nA sliding window remembers the ticks of the requests it recorded for a key. Advancing it to a tick forgets every remembered tick at or before the tick minus the span, so the window covers the `span` ticks ending at the current one. It allows a request when fewer than `limit` ticks remain remembered, and recording one remembers this tick.\n\n`replay` prints one line per event in log order: `<tick> <key> allow`, or `<tick> <key> deny <policy>` naming the first policy on the route, in the order the route wrote them, that refused. `summary` instead prints `<key> allowed=<a> denied=<d>` for every key that saw an event, in ascending key order, and then `total allowed=<a> denied=<d>`.\n\nA failure writes one line to standard error and exits 2, having written nothing to standard output; stop at the first one. The messages are `error: usage: cli.js replay|summary` when the argument is not exactly one of the two mode words, and otherwise `error: line N: <reason>` where the reason is one of `unknown directive <word>`, `expected bucket <name> <capacity> <refill> <per>`, `expected window <name> <limit> <span>`, `expected route <prefix> <policy>...`, `expected event <tick> <key>`, `invalid policy name <name>`, `invalid route prefix <prefix>`, `invalid key <key>`, `policy <name> is declared twice`, `prefix <prefix> is routed twice`, `unknown policy <name>`, `declarations must come before the first event`, `tick T is before tick P`, and `<field> must be an integer of at least <least>` naming the field as `capacity`, `refill`, `per`, `limit`, `span` or `tick`.",
  "heldOut": false,
  "immutable": [
    "test",
    "package.json"
  ],
  "checks": [
    {
      "id": "tests-pass",
      "outcome": "the test suite passes",
      "run": "node --test test/*.test.js"
    },
    {
      "id": "no-dependencies",
      "outcome": "no packages were installed",
      "run": "test ! -e node_modules"
    },
    {
      "id": "spec-cases",
      "outcome": "the program follows the written specification on the validator's own inputs",
      "run": "node src/cli.js",
      "cases": "reference/cases.json"
    }
  ]
}

/** Names and values: the scalar forms, arrays, and inline tables of one line. */

/** Raised for input the specification rejects; `line` is filled in by the caller. */
export class ConfError extends Error {
  /**
   * @param message - the reported reason.
   */
  constructor(message) {
    super(message)
    this.name = 'ConfError'
  }
}

/** A bare name: letters, digits, underscore and dash. */
const BARE = /^[A-Za-z0-9_-]+$/u

/** An integer: an optional sign and digit runs joined by single underscores. */
const INTEGER = /^[+-]?[0-9]+(?:_[0-9]+)*$/u

/** A float: an integer part, then a fraction, an exponent, or both. */
const FLOAT = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/u

/** The escapes a basic string carries. */
const ESCAPES = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }

/** A cursor over one line's text, shared by the name reader and the value reader. */
export class Reader {
  /**
   * @param text - the line, or the part of it still to read.
   */
  constructor(text) {
    this.text = text
    this.at = 0
  }

  /** Skip spaces and tabs. */
  skip() {
    while (this.text[this.at] === ' ' || this.text[this.at] === '\t') this.at += 1
  }

  /** The character at the cursor, or `undefined` past the end. */
  peek() {
    return this.text[this.at]
  }

  /** Consume the given text when it sits at the cursor. */
  eat(what) {
    if (!this.text.startsWith(what, this.at)) return false
    this.at += what.length
    return true
  }

  /** Read one quoted string, decoding a basic string's escapes. */
  string() {
    const quote = this.text[this.at]
    this.at += 1
    let value = ''
    for (;;) {
      const character = this.text[this.at]
      if (character === undefined) throw new ConfError('unterminated string')
      if (character === quote) {
        this.at += 1
        return value
      }
      if (quote === "'" || character !== '\\') {
        value += character
        this.at += 1
        continue
      }
      const marker = this.text[this.at + 1]
      if (marker !== undefined && marker in ESCAPES) {
        value += ESCAPES[marker]
        this.at += 2
        continue
      }
      if (marker === 'u' && /^[0-9A-Fa-f]{4}/u.test(this.text.slice(this.at + 2))) {
        value += String.fromCharCode(Number.parseInt(this.text.slice(this.at + 2, this.at + 6), 16))
        this.at += 6
        continue
      }
      throw new ConfError(`invalid escape \\${marker ?? ''}`)
    }
  }

  /**
   * Read one dotted name, whose parts are bare words or basic strings.
   * @returns the parts, in order.
   * @throws {ConfError} when a part is missing or malformed.
   */
  name() {
    const parts = []
    for (;;) {
      this.skip()
      const character = this.peek()
      if (character === '"' || character === "'") parts.push(this.string())
      else {
        const start = this.at
        while (this.peek() !== undefined && BARE.test(this.peek())) this.at += 1
        const word = this.text.slice(start, this.at)
        if (word === '') throw new ConfError('expected a name')
        parts.push(word)
      }
      this.skip()
      if (!this.eat('.')) return parts
    }
  }

  /**
   * Read one value: a scalar, an array, or an inline table.
   * @returns the value as `{ type, value }`, with `table` and `array` carrying their contents.
   * @throws {ConfError} when the value is malformed.
   */
  value() {
    this.skip()
    const character = this.peek()
    if (character === undefined) throw new ConfError('expected a value')
    if (character === '"' || character === "'") return { type: 'string', value: this.string() }
    if (character === '[') return this.array()
    if (character === '{') return this.inline()
    const start = this.at
    while (this.peek() !== undefined && !' \t,]}'.includes(this.peek())) this.at += 1
    const word = this.text.slice(start, this.at)
    if (word === 'true' || word === 'false') return { type: 'boolean', value: word === 'true' }
    const plain = word.replaceAll('_', '')
    if (INTEGER.test(word)) return { type: 'integer', value: Number(plain) }
    if (FLOAT.test(word)) return { type: 'float', value: Number(plain) }
    throw new ConfError(`invalid value ${word}`)
  }

  /** Read a bracketed array, whose items may themselves be arrays or inline tables. */
  array() {
    this.at += 1
    const items = []
    for (;;) {
      this.skip()
      if (this.peek() === undefined) throw new ConfError('unterminated array')
      if (this.eat(']')) return { type: 'array', value: items }
      items.push(this.value())
      this.skip()
      if (this.eat(',')) continue
      this.skip()
      if (this.eat(']')) return { type: 'array', value: items }
      throw new ConfError('unterminated array')
    }
  }

  /** Read a braced inline table, whose keys may be dotted. */
  inline() {
    this.at += 1
    const table = { type: 'table', value: new Map() }
    this.skip()
    if (this.eat('}')) return table
    for (;;) {
      const parts = this.name()
      this.skip()
      if (!this.eat('=')) throw new ConfError('expected = in an inline table')
      const held = this.value()
      let target = table
      for (const part of parts.slice(0, -1)) {
        const next = target.value.get(part) ?? { type: 'table', value: new Map() }
        if (next.type !== 'table') throw new ConfError(`${part} is not a table`)
        target.value.set(part, next)
        target = next
      }
      const last = parts[parts.length - 1]
      if (target.value.has(last)) throw new ConfError(`key ${parts.join('.')} is defined twice`)
      target.value.set(last, held)
      this.skip()
      if (this.eat(',')) continue
      this.skip()
      if (this.eat('}')) return table
      throw new ConfError('unterminated inline table')
    }
  }
}

/** The document: headers, dotted keys, and the tree they build. */

import { ConfError, Reader } from './value.js'

/** A table node the parser builds; `explicit` marks one a header declared itself. */
function table() {
  return { type: 'table', value: new Map(), explicit: false }
}

/** Walk to the table at `parts`, creating the tables on the way. */
function descend(root, parts, path) {
  let current = root
  for (let index = 0; index < parts.length; index += 1) {
    const part = parts[index]
    let next = current.value.get(part)
    if (next === undefined) {
      next = table()
      current.value.set(part, next)
    } else if (next.type === 'tables') next = next.value[next.value.length - 1]
    if (next.type !== 'table') throw new ConfError(`${[...path, ...parts.slice(0, index + 1)].join('.')} is not a table`)
    current = next
  }
  return current
}

/** Require the rest of a line to be blank or a comment. */
function endOfLine(reader, what) {
  reader.skip()
  const rest = reader.peek()
  if (rest !== undefined && rest !== '#' && rest !== ';') throw new ConfError(`trailing text after ${what}`)
}

/**
 * Parse the whole document into a tree of tables, arrays of tables, and values.
 * @param lines - the input lines, in order.
 * @returns the root table.
 * @throws {ConfError} carrying a `line` for any malformed or conflicting directive.
 */
export function parse(lines) {
  const root = table()
  let current = root
  let currentPath = []
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    try {
      const reader = new Reader(raw)
      reader.skip()
      const first = reader.peek()
      if (first === undefined || first === '#' || first === ';') continue
      if (first === '[') {
        reader.at += 1
        const array = reader.eat('[')
        const parts = reader.name()
        if (!reader.eat(']') || (array && !reader.eat(']'))) throw new ConfError('unterminated table header')
        endOfLine(reader, 'a table header')
        const parent = descend(root, parts.slice(0, -1), [])
        const last = parts[parts.length - 1]
        const held = parent.value.get(last)
        if (array) {
          if (held !== undefined && held.type !== 'tables') throw new ConfError(`${parts.join('.')} is not an array of tables`)
          const list = held ?? { type: 'tables', value: [] }
          const fresh = table()
          fresh.explicit = true
          list.value.push(fresh)
          parent.value.set(last, list)
          current = fresh
        } else {
          if (held !== undefined && (held.type !== 'table' || held.explicit)) throw new ConfError(`table ${parts.join('.')} is defined twice`)
          const fresh = held ?? table()
          fresh.explicit = true
          parent.value.set(last, fresh)
          current = fresh
        }
        currentPath = parts
        continue
      }
      const parts = reader.name()
      reader.skip()
      if (!reader.eat('=')) throw new ConfError('expected key = value')
      const held = reader.value()
      endOfLine(reader, 'a value')
      const target = descend(current, parts.slice(0, -1), currentPath)
      const last = parts[parts.length - 1]
      if (target.value.has(last)) throw new ConfError(`key ${[...currentPath, ...parts].join('.')} is defined twice`)
      target.value.set(last, held)
    } catch (error) {
      if (!(error instanceof ConfError)) throw error
      error.line = index + 1
      throw error
    }
  }
  return root
}

/** The plain JSON value of one node, with every table's keys sorted. */
export function toJson(node) {
  if (node.type === 'table') {
    return Object.fromEntries([...node.value.keys()].sort().map(key => [key, toJson(node.value.get(key))]))
  }
  if (node.type === 'tables' || node.type === 'array') return node.value.map(toJson)
  return node.value
}

/**
 * Every node below the root, as a dotted path and the type it holds.
 * @param node - the node to walk.
 * @param path - the path already walked.
 * @returns one `{ path, type }` per node below this one, tables' keys in sorted order.
 */
export function walk(node, path = '') {
  const out = []
  if (node.type === 'table') {
    for (const key of [...node.value.keys()].sort()) {
      const child = node.value.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push({ path: childPath, type: child.type === 'tables' ? 'array' : child.type })
      out.push(...walk(child, childPath))
    }
    return out
  }
  if (node.type === 'tables' || node.type === 'array') {
    node.value.forEach((child, index) => {
      const childPath = `${path}[${index}]`
      out.push({ path: childPath, type: child.type === 'tables' ? 'array' : child.type })
      out.push(...walk(child, childPath))
    })
  }
  return out
}

#!/usr/bin/env node
/** The command: `json` prints the canonical document, `keys` its paths and types. */

import { readFileSync } from 'node:fs'
import { parse, toJson, walk } from './document.js'
import { ConfError } from './value.js'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Every input line, with the trailing newline's empty tail dropped. */
function lines() {
  const split = readFileSync(0, 'utf8').split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) fail('usage: cli.js json|keys')

let root
try {
  root = parse(lines())
} catch (error) {
  if (!(error instanceof ConfError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

const out = argv[0] === 'json'
  ? `${JSON.stringify(toJson(root), undefined, 2)}\n`
  : walk(root).map(one => `${one.path} ${one.type}\n`).join('')
process.stdout.write(out)

import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

test('a scalar assignment becomes one JSON member', () => {
  assert.deepEqual(run(['json'], 'a = 1
'), { code: 0, out: '{
  "a": 1
}
', err: '' })
})

test('members print in ascending key order', () => {
  assert.equal(run(['json'], 'b = 1
a = 2
').out, '{
  "a": 2,
  "b": 1
}
')
})

test('a basic string decodes its escapes', () => {
  assert.equal(run(['json'], 'a = "x\ty"
').out, '{
  "a": "x\ty"
}
')
})

test('a literal string keeps its backslashes', () => {
  assert.equal(run(['json'], "a = 'x\ty'
").out, '{
  "a": "x\\ty"
}
')
})

test('booleans are booleans', () => {
  assert.equal(run(['json'], 'a = true
b = false
').out, '{
  "a": true,
  "b": false
}
')
})

test('an integer may carry underscore separators', () => {
  assert.equal(run(['json'], 'a = 1_000
').out, '{
  "a": 1000
}
')
})

test('an array holds its items in order', () => {
  assert.equal(run(['json'], 'a = [1, 2]
').out, '{
  "a": [
    1,
    2
  ]
}
')
})

test('a table header nests the keys under it', () => {
  assert.equal(run(['json'], '[s]
a = 1
').out, '{
  "s": {
    "a": 1
  }
}
')
})

test('a dotted header nests two levels', () => {
  assert.equal(run(['json'], '[s.t]
a = 1
').out, '{
  "s": {
    "t": {
      "a": 1
    }
  }
}
')
})

test('a doubled header appends to an array of tables', () => {
  assert.equal(run(['json'], '[[i]]
a = 1
[[i]]
a = 2
').out, '{
  "i": [
    {
      "a": 1
    },
    {
      "a": 2
    }
  ]
}
')
})

test('comments and blank lines are ignored', () => {
  assert.equal(run(['json'], '# note

a = 1 # tail
').out, '{
  "a": 1
}
')
})

test('an empty document is an empty object', () => {
  assert.deepEqual(run(['json'], ''), { code: 0, out: '{}
', err: '' })
})

test('keys list every path with its type', () => {
  assert.equal(run(['keys'], '[s]
a = 1
b = "x"
').out, 's table
s.a integer
s.b string
')
})

test('keys tell an integer from a float', () => {
  assert.equal(run(['keys'], 'a = 1
b = 1.5
').out, 'a integer
b float
')
})

test('a key defined twice is rejected', () => {
  const result = run(['json'], 'a = 1
a = 2
')
  assert.equal(result.code, 2)
  assert.equal(result.out, '')
  assert.equal(result.err, 'error: line 2: key a is defined twice
')
})

test('a table header used twice is rejected', () => {
  assert.equal(run(['json'], '[s]
[s]
').err, 'error: line 2: table s is defined twice
')
})

test('a value that parses as nothing is rejected', () => {
  assert.equal(run(['json'], 'a = nope
').err, 'error: line 1: invalid value nope
')
})

test('an unknown mode is rejected', () => {
  const result = run(['toml'], '')
  assert.equal(result.code, 2)
  assert.equal(result.err, 'error: usage: cli.js json|keys
')
})

