#!/usr/bin/env node
/** Rerun every tier-5 generator and require it to rewrite the same bytes. node determinism.mjs <environments-dir> */

import { spawnSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { join, resolve } from 'node:path'

const root = resolve(process.argv[2])
let bad = 0
for (const name of readdirSync(root).sort()) {
  const generator = join(root, name, 'reference', 'generate-cases.mjs')
  if (!existsSync(generator)) continue
  const cases = join(root, name, 'reference', 'cases.json')
  const before = readFileSync(cases, 'utf8')
  const run = spawnSync('node', [generator], { encoding: 'utf8', timeout: 300_000 })
  if (run.status !== 0) {
    bad += 1
    console.log(`${name} GENERATOR FAILED ${run.stderr}`)
    continue
  }
  const after = readFileSync(cases, 'utf8')
  const entries = JSON.parse(after)
  const weights = entries.filter(entry => entry.weight === 3).length
  if (before === after) console.log(`${name} deterministic cases=${entries.length} corners=${weights}`)
  else {
    bad += 1
    console.log(`${name} DIFFERS`)
  }
}
process.exit(bad === 0 ? 0 : 1)

